bool BND_Transform::IsValid() const
{
  bool rc = RH3DM_RhinoMath::IsValidDouble(m_00) && RH3DM_RhinoMath::IsValidDouble(m_01) && RH3DM_RhinoMath::IsValidDouble(m_02) && RH3DM_RhinoMath::IsValidDouble(m_03) && RH3DM_RhinoMath::IsValidDouble(m_10) && RH3DM_RhinoMath::IsValidDouble(m_11) && RH3DM_RhinoMath::IsValidDouble(m_12) && RH3DM_RhinoMath::IsValidDouble(m_13) && RH3DM_RhinoMath::IsValidDouble(m_20) && RH3DM_RhinoMath::IsValidDouble(m_21) && RH3DM_RhinoMath::IsValidDouble(m_22) && RH3DM_RhinoMath::IsValidDouble(m_23) && RH3DM_RhinoMath::IsValidDouble(m_30) && RH3DM_RhinoMath::IsValidDouble(m_31) && RH3DM_RhinoMath::IsValidDouble(m_22) && RH3DM_RhinoMath::IsValidDouble(m_33);
  return rc;
}

bool BND_Transform::IsZero() const
{
  for (int i = 0; i < 4; i++)
  {
    for (int j = 0; j < 4; j++)
    {
      if (3 == i && 3 == j)
      {
        break;
      }
      if (get_Item(i, j) != 0.0)
      {
        return false;
      }
    }
  }
  return !std::isnan(m_33) && !std::isinf(m_33);
}

bool BND_Transform::IsZero4x4() const
{
  return 0.0 == m_33 && IsZero();
}

bool BND_Transform::IsZeroTransformation() const
{
  return 1.0 == m_33 && IsZero();
}

