std::vector<BND_Point3d> BND_Transform::TransformList(const std::vector<BND_Point3d>& points) const
{
  std::vector<BND_Point3d> rc = std::vector<BND_Point3d>(points.begin(), points.end());
  for (int i = 0; i < ((int)rc.size()); i++)
  {
    BND_Point3d pt = rc[i];
    (pt).Transform((*this));
    rc[i] = pt;
  }
  return rc;
}

