BND_Transform BND_Transform::Transpose() const
{
  BND_Transform rc = BND_Transform();
  for (int r = 0; r < 4; r++)
  {
    for (int c = 0; c < 4; c++)
    {
      rc.set_Item(r, c, get_Item(c, r));
    }
  }
  return rc;
}

